import{_ as n,C as t,o as s,c as o,a4 as e,b as r,w as i,a as p,E as c,a5 as d}from"./chunks/framework.BRzJ4ijD.js";const C=JSON.parse('{"title":"寄存器分配：Graph Coloring & Linear Scan","description":"","frontmatter":{},"headers":[],"relativePath":"compilers/codegen/regalloc.md","filePath":"compilers/codegen/regalloc.md","lastUpdated":1788475713000}'),h={name:"compilers/codegen/regalloc.md"};function g(u,a,v,b,k,m){const l=t("Mermaid");return s(),o("div",null,[a[1]||(a[1]=e(`<h1 id="寄存器分配-graph-coloring-linear-scan" tabindex="-1">寄存器分配：Graph Coloring &amp; Linear Scan <a class="header-anchor" href="#寄存器分配-graph-coloring-linear-scan" aria-label="Permalink to &quot;寄存器分配：Graph Coloring &amp; Linear Scan&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>寄存器分配把无限虚拟寄存器映射到有限物理寄存器。<strong>两个算法家族</strong>：Graph Coloring（Chaitin 1981, 经典 NP-hard 但质量最高）—— 把&quot;同时活跃的虚拟寄存器&quot;建成干涉图，相邻不共色的就 spill；Linear Scan（Poletto &amp; Sarkar 1999）—— 不建图、按起点快排扫描 live interval 区间、立即分配——快 10 倍、质量稍差但够 JIT 用。现代 LLVM 把 Graph Coloring 做得工业级，HotSpot、V8、Cranelift 都偏 Linear Scan 变种。理解 spill、copy coalescing、calling convention、register pressure 是这章的核心。</p><hr><h2 id="一、活跃性分析-liveness" tabindex="-1">一、活跃性分析 (Liveness) <a class="header-anchor" href="#一、活跃性分析-liveness" aria-label="Permalink to &quot;一、活跃性分析 (Liveness)&quot;">​</a></h2><h3 id="live-in-live-out" tabindex="-1">Live-In / Live-Out <a class="header-anchor" href="#live-in-live-out" aria-label="Permalink to &quot;Live-In / Live-Out&quot;">​</a></h3><p>一个变量在某个 program point 是 live 的，当存在从该点出发的 path 里的 use 没被中间 def 覆盖。形式化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>live_in[b]  = use[b] ∪ (live_out[b] - def[b])</span></span>
<span class="line"><span>live_out[b] = ∪ live_in[s]    for s ∈ succs(b)</span></span></code></pre></div><p>迭代到底不动点（典型 dataflow equation）。这是后向分析 (backward analysis)。</p><h3 id="live-ranges-live-intervals" tabindex="-1">Live ranges &amp; live intervals <a class="header-anchor" href="#live-ranges-live-intervals" aria-label="Permalink to &quot;Live ranges &amp; live intervals&quot;">​</a></h3><p>在一个 basic block 内连续活跃的虚拟寄存器 = live interval <code>[start_pos, end_pos]</code>。SSA-down 后dealloc&#39;d 后，变量的 live range = 一系列 live interval 段，并起来。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%1 = ...</span></span>
<span class="line"><span>... %1 ...     ; %1 live 第 1-5 行</span></span>
<span class="line"><span>%2 = ...</span></span>
<span class="line"><span>... %2 ...     ; %2 live 第 6-10 行</span></span></code></pre></div>`,12)),(s(),r(d,null,{default:i(()=>[c(l,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%251%20li%5B1%2C5%5D%22%5D%20--%3E%20C%5Boverlap%3F%5D%0A%20%20%20%20B%5B%22%252%20li%5B6%2C10%5D%22%5D%20--%3E%20C%0A%20%20%20%20C%20--%3E%7Cno%7C%20D%5B%251%2C%20%252%20%E5%8F%AF%E5%85%B1%E5%88%86%E9%85%8D%E5%90%8C%E4%B8%80%E7%89%A9%E7%90%86%E5%AF%84%E5%AD%98%E5%99%A8%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e(`<p>不重叠 → 不干涉 → 可同色 → 可共分配同一物理寄存器。这是 graph coloring 的基础。</p><hr><h2 id="二、干涉图-interference-graph" tabindex="-1">二、干涉图 (Interference Graph) <a class="header-anchor" href="#二、干涉图-interference-graph" aria-label="Permalink to &quot;二、干涉图 (Interference Graph)&quot;">​</a></h2><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // live: [1..5]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // live: [3..7]</span></span></code></pre></div><p><code>%a</code> 和 <code>%b</code> 在 [3, 5] 重叠 → <strong>interfere</strong> → 必须不同颜色（不同物理寄存器）。</p><p>构建干涉图：</p><ol><li>跑 liveness analysis 得每个 vreg 的 live interval</li><li>对每两 live interval <code>i</code>、<code>j</code>：若 overlap，加边 <code>(i, j)</code></li><li>同时考虑 <strong>pre-colored</strong> node（必须固定到物理寄存器——比如 calling convention 要求参数在 <code>%rdi</code> / <code>%rsi</code>）</li></ol><h3 id="pre-colored-example-x86-64-sysv-abi" tabindex="-1">Pre-colored Example (x86-64 SysV ABI) <a class="header-anchor" href="#pre-colored-example-x86-64-sysv-abi" aria-label="Permalink to &quot;Pre-colored Example (x86-64 SysV ABI)&quot;">​</a></h3><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b; }</span></span></code></pre></div><p><code>a</code> 必须在 <code>%rdi</code>，<code>b</code> 必须在 <code>%rsi</code>——call convention 强制。这些 vreg 是 pre-colored：</p><ul><li><code>%arg_a</code> → 已经是 <code>%rdi</code> （色 = RDI）</li><li><code>%arg_b</code> → 已经是 <code>%rsi</code> （色 = RSI）</li></ul><p>干涉图上其他 vreg 必须避免占这俩色。</p><hr><h2 id="三、graph-coloring-算法" tabindex="-1">三、Graph Coloring 算法 <a class="header-anchor" href="#三、graph-coloring-算法" aria-label="Permalink to &quot;三、Graph Coloring 算法&quot;">​</a></h2><h3 id="chaitin-briggs-classic" tabindex="-1">Chaitin-Briggs (classic) <a class="header-anchor" href="#chaitin-briggs-classic" aria-label="Permalink to &quot;Chaitin-Briggs (classic)&quot;">​</a></h3><p>Kempe&#39;s heuristic:</p><ol><li><strong>Simplification</strong>: 找 degree &lt; K (K = 物理寄存器数) 的 node，push 到 stack 后从图删。</li><li>直到所有 node 都 &lt; K，或剩下的都 ≥ K（spill 候选）。</li><li><strong>Spill</strong>: 选一个 spill 候选，标记为 spill；不分配物理寄存器，运行时通过 stack。</li><li><strong>Select</strong>: pop stack，分配尚未被邻居占用的颜色。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loop:</span></span>
<span class="line"><span>   if exists node with degree &lt; K:</span></span>
<span class="line"><span>      stack.push(node); remove from graph</span></span>
<span class="line"><span>   else:</span></span>
<span class="line"><span>      pick highest cost / least frequently spilled; mark potential_spill</span></span>
<span class="line"><span>      stack.push(node); remove from graph</span></span>
<span class="line"><span>until graph empty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while not stack.empty:</span></span>
<span class="line"><span>   n = stack.pop()</span></span>
<span class="line"><span>   if can color: pick color avoiding neighbors</span></span>
<span class="line"><span>   else: actually_spill (regenerate IR with loaded value)</span></span></code></pre></div><p>迭代 spill: spill 后重新跑 liveness，可能产生新 node 然后再 round，直到全部 on reg 或确认稳定的 spill 集。</p><h3 id="chaitin-vs-briggs" tabindex="-1">Chaitin vs Briggs <a class="header-anchor" href="#chaitin-vs-briggs" aria-label="Permalink to &quot;Chaitin vs Briggs&quot;">​</a></h3><ul><li><strong>Chaitin</strong>: 直接选 spill 候选 + drop，扫整图后重做。</li><li><strong>Briggs</strong>: optimistic spill——pop 时若实际有 color，不算 spill。Briggs 的 reverse order 让 optimistic 多一次机会。</li></ul><p>工业 LLVM 用 <strong>PBQP (Partitioned Boolean Quadratic Programming)</strong> 求解器 / <strong>Greedy</strong> coloring 跨大图好。</p><h3 id="实例-coloring" tabindex="-1">实例 Coloring <a class="header-anchor" href="#实例-coloring" aria-label="Permalink to &quot;实例 Coloring&quot;">​</a></h3><p>K = 3 (3 个物理寄存器 R0/R1/R2)，干涉图:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A — B</span></span>
<span class="line"><span>|   |</span></span>
<span class="line"><span>D — C</span></span></code></pre></div><p>四 node 都相互干涉 (clique K4)：</p><ul><li>K4 degree 是 3 = K，不能 simplify</li><li>选 B spill（标记 spill 后再 iter）</li><li>实际：希望重新跑把 B 全部加载 / 重命名拆干 → B 重新成两个更短间隔 → 不重叠 → 上色</li></ul><h3 id="cost-function-for-spill" tabindex="-1">Cost Function for Spill <a class="header-anchor" href="#cost-function-for-spill" aria-label="Permalink to &quot;Cost Function for Spill&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spill_cost(v) = 使用次数 × load/store 单价 / live interval 长度</span></span></code></pre></div><p>长 live range 上 spill 不划算（频繁 load/store），短 range 上 spill 划算。</p><hr><h2 id="四、linear-scan" tabindex="-1">四、Linear Scan <a class="header-anchor" href="#四、linear-scan" aria-label="Permalink to &quot;四、Linear Scan&quot;">​</a></h2><p>Poletto-Sarkar Linear Scan：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 把所有 live interval 按 start_pos 排序</span></span>
<span class="line"><span>2. 维护 active list: 当前分配中的 interval</span></span>
<span class="line"><span>3. for each interval i (in start order):</span></span>
<span class="line"><span>     expire_old_intervals(i.start)  # end &lt; i.start 的从 active list 删除、还寄存器</span></span>
<span class="line"><span>     if free_reg:</span></span>
<span class="line"><span>        assign free_reg to i</span></span>
<span class="line"><span>     else:</span></span>
<span class="line"><span>        spill_at_interval(i)        # 选 spill 候选：</span></span>
<span class="line"><span>                                     #   - active list 中 end_pos 最大者</span></span>
<span class="line"><span>                                     #   - 如果它的 end_pos &gt; i.end_pos:</span></span>
<span class="line"><span>                                     #     spill 它, 把 i 放到它腾的 reg</span></span>
<span class="line"><span>                                     #   - 否则 spill 自身 i</span></span>
<span class="line"><span>     push i to active list</span></span></code></pre></div><p>O(N log N) 排序 + O(N) 扫描。比 graph coloring 快 10-30 倍。</p><h3 id="现代改进-traub-s-linear-scan-llvm-hotspot" tabindex="-1">现代改进: Traub&#39;s Linear Scan (LLVM / HotSpot) <a class="header-anchor" href="#现代改进-traub-s-linear-scan-llvm-hotspot" aria-label="Permalink to &quot;现代改进: Traub&#39;s Linear Scan (LLVM / HotSpot)&quot;">​</a></h3><ul><li><strong>Live Interval split</strong>: 在压力高的点把 long interval 拆成多段，每段独立分配——可 spill 一部分留寄存器另一部分。</li><li><strong>Position-aware spill</strong>: 不只&quot;spill 不在寄存器时 load&quot;，而是常用寄存器 cache 最近 use 模式。</li><li><strong>Hinted register</strong>: 优先选相同 hint 的色——减少 copy coalescing pain。</li></ul><h3 id="实例-linear-scan" tabindex="-1">实例 Linear Scan <a class="header-anchor" href="#实例-linear-scan" aria-label="Permalink to &quot;实例 Linear Scan&quot;">​</a></h3><p>K = 2，三个 live intervals:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v1: [1..10]    v2: [2..5]         v3: [6..12]</span></span></code></pre></div><p>按 start sort: v1, v2, v3.</p><ol><li>v1: active = [v1], reg[v1] = R0</li><li>v2: active = [v1, v2], reg[v2] = R1</li><li>v3: expire ≤ 5: v2 expire → active = [v1], free R1. v3 = R1. active = [v1, v3]</li><li>return: reg[v1]=R0, reg[v3]=R1</li></ol><p>完美使用 K=2 即可——active list 最多 ⌈K⌉ 个 node。</p><hr><h2 id="五、copy-coalescing" tabindex="-1">五、Copy Coalescing <a class="header-anchor" href="#五、copy-coalescing" aria-label="Permalink to &quot;五、Copy Coalescing&quot;">​</a></h2><h3 id="source-of-copies" tabindex="-1">Source of copies <a class="header-anchor" href="#source-of-copies" aria-label="Permalink to &quot;Source of copies&quot;">​</a></h3><div class="language-llvm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">llvm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%a = </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i32 @f()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%b = %a        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; copy</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%c = %b + %c</span></span></code></pre></div><p><code>%b</code> 是 <code>%a</code> 的 copy。如果分配器把 <code>%a</code> 和 <code>%b</code> 给同一个物理寄存器，copy 消失。</p><h3 id="move-coalescing" tabindex="-1">Move Coalescing <a class="header-anchor" href="#move-coalescing" aria-label="Permalink to &quot;Move Coalescing&quot;">​</a></h3><p>很多 copy 来自 calling convention：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%arg = %rdi        ; 第一个参数 copy 到 vreg 时</span></span></code></pre></div><p>很多 copy 来自 SSA destruction 的 φ 节点:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loop.header:</span></span>
<span class="line"><span>  %x = phi [ %xinit, %entry ], [ %xnext, %back ]</span></span></code></pre></div><p>SSA destruction 在每个 predecessor block 尾插 <code>mov %xinit, %x_phys</code>——这是一个 copy。</p><h3 id="coalescing-算法" tabindex="-1">Coalescing 算法 <a class="header-anchor" href="#coalescing-算法" aria-label="Permalink to &quot;Coalescing 算法&quot;">​</a></h3><ol><li><strong>Iterated Register Coalescing (IRC)</strong>: George-Appel 1996, 同时做 coalescing 与 simplification。coalesce edge (a,b): 若合并后 a∪b 的所有邻居都 &lt; K, OK。否则保守——可能 spill 成本升高。</li><li><strong>Briggs</strong>: 合并后邻居中 degree ≥ K 的数 &lt; K, OK。</li></ol><p>LLVM 与 HotSpot 都用 <strong>Briggs / IRC 改编</strong>。Cranelift 用更简单的 coalescer——速度优先。</p><hr><h2 id="六、register-pressure-spill-quality" tabindex="-1">六、Register Pressure &amp; Spill Quality <a class="header-anchor" href="#六、register-pressure-spill-quality" aria-label="Permalink to &quot;六、Register Pressure &amp; Spill Quality&quot;">​</a></h2><h3 id="pressure" tabindex="-1">Pressure <a class="header-anchor" href="#pressure" aria-label="Permalink to &quot;Pressure&quot;">​</a></h3><p>N vreg 同时 live = pressure N。如果 stress = N &gt; K，必须 spill。</p><p>LLVM 在 IR 阶段就能 audit pressure——通过剪压阈值如 heuristic (about-ish: if predicted pressure &gt; K, abort a pass early)。该机制让编译器能主动放弃 aggressive inline（避免压力爆）。</p><h3 id="spill-mode" tabindex="-1">Spill Mode <a class="header-anchor" href="#spill-mode" aria-label="Permalink to &quot;Spill Mode&quot;">​</a></h3><p><strong>Spill to Memory</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%v = add %a, %b         ; %v live</span></span>
<span class="line"><span>store %v, [stack slot]</span></span>
<span class="line"><span>...                      ; use of %v freed for re-use</span></span>
<span class="line"><span>%reload = load [stack slot]</span></span>
<span class="line"><span>use %reload</span></span></code></pre></div><p>但是 store+load 太 expensive —— profiler 上 spill-to-memory 比 spill-more-load (just-reload-on-use) 慢 3 倍。</p><p><strong>Spill at Use (better)</strong>: 只在使用前 load:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%v = add %a, %b</span></span>
<span class="line"><span>store %v, [stack slot]</span></span>
<span class="line"><span>...                      ; %v not used here</span></span>
<span class="line"><span>... </span></span>
<span class="line"><span>%reload = load [stack slot]</span></span>
<span class="line"><span>%r2 = add %reload, %c</span></span></code></pre></div><p>Clever allocator 把 spill value 重新 split: 有时 load + use + free reg + reload + use。</p><h3 id="rematerialization" tabindex="-1">Rematerialization <a class="header-anchor" href="#rematerialization" aria-label="Permalink to &quot;Rematerialization&quot;">​</a></h3><p>某些值重新计算比 spill 便宜——比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%c = const 5</span></span>
<span class="line"><span>...use %c</span></span>
<span class="line"><span>...long live range overlap</span></span>
<span class="line"><span>...use %c again</span></span></code></pre></div><p>不必 store <code>%c = 5</code> 然后再 load。直接用<strong>一个新的 <code>mov $5, %r</code></strong> 替代 load —— cycle 数相同、 不需 stack slot。识别&quot;cheap-to-remat&quot; 值是 allocator 的 quality gain。</p><hr><h2 id="七、calling-convention" tabindex="-1">七、Calling Convention <a class="header-anchor" href="#七、calling-convention" aria-label="Permalink to &quot;七、Calling Convention&quot;">​</a></h2><h3 id="caller-saved-vs-callee-saved" tabindex="-1">Caller-saved vs Callee-saved <a class="header-anchor" href="#caller-saved-vs-callee-saved" aria-label="Permalink to &quot;Caller-saved vs Callee-saved&quot;">​</a></h3><p>ABI 定义：</p><ul><li><strong>Caller-saved</strong> (volatile): 调用方负责保存的寄存器。若调用方 live value 占这寄存器，必须 call 前 push、return 后 pop。 <ul><li>x86-64 SysV: RAX, RCX, RDX, RSI, RDI, R8-R11 + XMM0-15</li><li>ARM64 AAPCS: X0-X18 (X0-X7 args, X9-X15 temps, X8/X16/X17 special)</li></ul></li><li><strong>Callee-saved</strong> (non-volatile): 被调方负责保存的寄存器。callee 用这些 reg 前必须 prologue push、epilogue pop。 <ul><li>x86-64 SysV: RBX, RBP, R12-R15</li><li>ARM64 AAPCS: X19-X28</li></ul></li></ul><h3 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h3><p>callee-saved 寄存器需要保存—— 哪怕 callee 函数没用 X19 也不用 push；用就要 push + pop。<strong>Strategy</strong>:allocator 倾向先用 caller-saved 寄存器（短函数里没子调用就行），然后才 callee-saved。这对短 leaf function 至关重要——LLVM 的 <code>PrologEpilogInserter</code>pass 做这个。</p><h3 id="function-attributes" tabindex="-1">Function attributes <a class="header-anchor" href="#function-attributes" aria-label="Permalink to &quot;Function attributes&quot;">​</a></h3><p><code>norecurse</code>、<code>leaf</code>、<code>nounwind</code> 等属性帮助 allocator 判断 callee-save 寄存器能省。无子调用且 leaf 的函数可以不保存 caller-saved。</p><hr><h2 id="八、架构变种" tabindex="-1">八、架构变种 <a class="header-anchor" href="#八、架构变种" aria-label="Permalink to &quot;八、架构变种&quot;">​</a></h2><h3 id="x86-麻烦事" tabindex="-1">x86 麻烦事 <a class="header-anchor" href="#x86-麻烦事" aria-label="Permalink to &quot;x86 麻烦事&quot;">​</a></h3><ul><li>8 GPR（x86-64）：RAX, RCX, RDX, RBX, RSI, RDI, R8-R15. 14-16 if count RSP/RBP reserved.</li><li>RBP 由 LLVM 默认作 frame pointer（debug-frame 风险），后 <code>-fomit-frame-pointer</code> 可省。</li><li>XMM 寄存器（16 SSE/AVX）：很多工程代码不用，但 vectorize 时的 pressure 大。</li><li>32bit x86 只有 6 GPR，压力极大。</li></ul><h3 id="arm64" tabindex="-1">ARM64 <a class="header-anchor" href="#arm64" aria-label="Permalink to &quot;ARM64&quot;">​</a></h3><ul><li>31 X 寄存器 (X0-X30, X31 = SP / Zero)，鲜少 pressure。</li><li>SIMD/FP 同一批寄存器。</li></ul><h3 id="risc-v" tabindex="-1">RISC-V <a class="header-anchor" href="#risc-v" aria-label="Permalink to &quot;RISC-V&quot;">​</a></h3><ul><li>31 GPR, 标准 ABI RV64G。</li><li>浮点是独立 X0..X31 register file——若架构有 F/D 扩展。</li></ul><hr><h2 id="九、易错清单" tabindex="-1">九、易错清单 <a class="header-anchor" href="#九、易错清单" aria-label="Permalink to &quot;九、易错清单&quot;">​</a></h2><ol><li><strong>ABI 不保存的寄存器、allocator 假设保存了 → caller-side bug</strong>：Rust 曾有 LLVM bug 把 XMM 假设 saved 导致 SSE spill 后 FP-clobbered 出错。</li><li><strong>leaf function 太长 spill 到 callee-saved 让 cycle cost 高</strong>: profile shows callee-save spill+restore is 5-10 cycle × multi 行——很多函数实际编译 -O0 + leaf。</li><li><strong>register pressure &gt; 4</strong> → 向量化重 abort：很多 LLVM vec pass 会在压力过高时不再 vectorize，避免 spill 反而恶化。开发者看不到这种 abort、权当自动向量化假装生效。</li><li><strong>寄存器 hinting 错位</strong>：两个 copy vreg 但分配器没 coalesce → 仍有 mov, 性能小心脏。LLVM 输出 IR 中 <code>copy</code> 指令保留很容易 catch via <code>llc -print-after-all</code>。</li><li><strong>PGO 决定 spill cost</strong>: PGO 知道某个 use 实际热/冷，allocator 重 alloc 时优先热路径拥有 reg。Google Chrome、PGO-mode Chromium 都强烈受此影响。</li></ol><hr><h2 id="十、这一章带走的东西" tabindex="-1">十、这一章带走的东西 <a class="header-anchor" href="#十、这一章带走的东西" aria-label="Permalink to &quot;十、这一章带走的东西&quot;">​</a></h2><ol><li>寄存器分配本质是<strong>有限物理寄存器到无限虚拟寄存器 (vreg) 的映射</strong>, spill 是 fall-back。</li><li>Graph Coloring 经典算法——Chaitin-Briggs、Simplification、Select、Cost-based Spill,质量和复杂度最好。</li><li>Linear Scan 是 JIT 友好的简化——排序 + active list + immediate spill 决策。</li><li>Copy Coalescing 把&quot;是 copy 的两条 mov&quot; 删成 0——大部分 copy 来自 SSA destruction 与 ABI 强制。</li><li>Calling Convention 决定 caller-saved vs callee-saved 拆分——allocator 倾向 caller-saved for short leaf functions。</li><li>Spill 质量: spill-at-use 比 store-to-stack 便宜；remat <code>const N</code> 比 store 便宜。</li></ol><hr><p>下一节 → <a href="./jit">JIT、Tiered Compilation、V8 Turbofan、Cranelift</a></p>`,98))])}const y=n(h,[["render",g]]);export{C as __pageData,y as default};
